/**
 * C host for the self-hosted JavaScript C compiler.
 *
 * Embeds bytecode produced by qjsc for scripts/cc.js and its dependencies,
 * plus a small bootstrap that installs Buffer/process. Native helpers provide
 * the filesystem and process primitives the compiler needs.
 *
 * The embedded module table is generated by scripts/selfhost.js into
 * `modules.c`; see cc-selfhost.h for the shared declarations.
 */

#include <dirent.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "cc-selfhost.h"
#include "quickjs.h"
#include "quickjs-libc.h"

/* Top-level bundles, evaluated directly rather than through the loader. */
extern const uint8_t cc[];
extern const uint32_t cc_size;
extern const uint8_t cc_bootstrap[];
extern const uint32_t cc_bootstrap_size;

static const char *base_name(const char *path)
{
    const char *slash = strrchr(path, '/');
    return slash ? slash + 1 : path;
}

static JSValue throw_errno(JSContext *ctx, const char *what, const char *path)
{
    return JS_ThrowPlainError(ctx, "%s '%s': %s", what, path, strerror(errno));
}

static JSValue cc_read_file(JSContext *ctx, JSValueConst this_val,
                            int argc, JSValueConst *argv)
{
    size_t len;
    uint8_t *buf;
    JSValue ret;
    const char *path = JS_ToCString(ctx, argv[0]);

    (void)this_val;
    (void)argc;
    if (!path) return JS_EXCEPTION;
    buf = js_load_file(ctx, &len, path);
    if (!buf) {
        JS_FreeCString(ctx, path);
        return JS_NULL;
    }
    JS_FreeCString(ctx, path);
    ret = JS_NewArrayBufferCopy(ctx, buf, len);
    js_free(ctx, buf);
    return ret;
}

static JSValue cc_write_file(JSContext *ctx, JSValueConst this_val,
                             int argc, JSValueConst *argv)
{
    const char *path;
    const uint8_t *data = NULL;
    size_t len = 0;
    const char *str = NULL;
    JSValue ab = JS_UNDEFINED;
    FILE *fp;
    int ok;

    (void)this_val;
    (void)argc;
    path = JS_ToCString(ctx, argv[0]);
    if (!path) return JS_EXCEPTION;

    if (JS_IsString(argv[1])) {
        str = JS_ToCStringLen(ctx, &len, argv[1]);
        if (!str) {
            JS_FreeCString(ctx, path);
            return JS_EXCEPTION;
        }
        data = (const uint8_t *)str;
    } else if (JS_IsArrayBuffer(argv[1])) {
        data = JS_GetArrayBuffer(ctx, &len, argv[1]);
        if (!data) {
            JS_FreeCString(ctx, path);
            return JS_EXCEPTION;
        }
    } else if (JS_GetTypedArrayType(argv[1]) >= 0) {
        size_t offset, length, bytes_per_element;
        ab = JS_GetTypedArrayBuffer(ctx, argv[1], &offset, &length,
                                    &bytes_per_element);
        if (JS_IsException(ab)) {
            JS_FreeCString(ctx, path);
            return JS_EXCEPTION;
        }
        data = JS_GetArrayBuffer(ctx, &len, ab);
        if (!data) {
            JS_FreeValue(ctx, ab);
            JS_FreeCString(ctx, path);
            return JS_EXCEPTION;
        }
        data += offset;
        len = length;
    } else {
        str = JS_ToCStringLen(ctx, &len, argv[1]);
        if (!str) {
            JS_FreeCString(ctx, path);
            return JS_EXCEPTION;
        }
        data = (const uint8_t *)str;
    }

    fp = fopen(path, "wb");
    if (!fp) {
        throw_errno(ctx, "open", path);
        ok = -1;
    } else {
        ok = (fwrite(data, 1, len, fp) == len) ? 1 : 0;
        fclose(fp);
        if (!ok) JS_ThrowPlainError(ctx, "write '%s' failed", path);
    }

    if (str) JS_FreeCString(ctx, str);
    if (!JS_IsUndefined(ab)) JS_FreeValue(ctx, ab);
    JS_FreeCString(ctx, path);
    if (ok < 0) return JS_EXCEPTION;
    return JS_NewBool(ctx, ok);
}

static JSValue cc_exists(JSContext *ctx, JSValueConst this_val,
                         int argc, JSValueConst *argv)
{
    struct stat st;
    const char *path = JS_ToCString(ctx, argv[0]);
    int ret;

    (void)this_val;
    (void)argc;
    if (!path) return JS_EXCEPTION;
    ret = stat(path, &st) == 0;
    JS_FreeCString(ctx, path);
    return JS_NewBool(ctx, ret);
}

static JSValue cc_stat(JSContext *ctx, JSValueConst this_val,
                       int argc, JSValueConst *argv)
{
    struct stat st;
    JSValue obj;
    const char *path = JS_ToCString(ctx, argv[0]);
    int ret;

    (void)this_val;
    (void)argc;
    if (!path) return JS_EXCEPTION;
    ret = stat(path, &st);
    JS_FreeCString(ctx, path);
    if (ret < 0) return JS_NULL;

    obj = JS_NewObject(ctx);
    if (JS_IsException(obj)) return JS_EXCEPTION;
    JS_SetPropertyStr(ctx, obj, "mode", JS_NewInt32(ctx, st.st_mode));
    JS_SetPropertyStr(ctx, obj, "size", JS_NewInt64(ctx, st.st_size));
    JS_SetPropertyStr(ctx, obj, "isFile", JS_NewBool(ctx, S_ISREG(st.st_mode)));
    JS_SetPropertyStr(ctx, obj, "isDirectory", JS_NewBool(ctx, S_ISDIR(st.st_mode)));
    JS_SetPropertyStr(ctx, obj, "isSymbolicLink", JS_NewBool(ctx, S_ISLNK(st.st_mode)));
    return obj;
}

static JSValue cc_readdir(JSContext *ctx, JSValueConst this_val,
                          int argc, JSValueConst *argv)
{
    DIR *dir;
    struct dirent *entry;
    JSValue arr;
    uint32_t index = 0;
    const char *path = JS_ToCString(ctx, argv[0]);

    (void)this_val;
    (void)argc;
    if (!path) return JS_EXCEPTION;
    dir = opendir(path);
    if (!dir) {
        JS_FreeCString(ctx, path);
        return JS_NULL;
    }
    JS_FreeCString(ctx, path);

    arr = JS_NewArray(ctx);
    if (JS_IsException(arr)) {
        closedir(dir);
        return JS_EXCEPTION;
    }
    while ((entry = readdir(dir))) {
        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
        JS_SetPropertyUint32(ctx, arr, index++, JS_NewString(ctx, entry->d_name));
    }
    closedir(dir);
    return arr;
}

static int mkdir_recursive(const char *path)
{
    char *copy = strdup(path);
    char *p;
    int ret = 0;

    if (!copy) return 0;
    for (p = copy + 1; *p; p++) {
        if (*p != '/') continue;
        *p = '\0';
        if (mkdir(copy, 0777) < 0 && errno != EEXIST) {
            free(copy);
            return 0;
        }
        *p = '/';
    }
    if (mkdir(copy, 0777) < 0 && errno != EEXIST) ret = 0;
    else ret = 1;
    free(copy);
    return ret;
}

static JSValue cc_mkdir(JSContext *ctx, JSValueConst this_val,
                        int argc, JSValueConst *argv)
{
    const char *path = JS_ToCString(ctx, argv[0]);
    int recursive = 0;
    int ret;

    (void)this_val;
    if (!path) return JS_EXCEPTION;
    if (argc >= 2) recursive = JS_ToBool(ctx, argv[1]);
    if (recursive) {
        ret = mkdir_recursive(path);
    } else {
        ret = mkdir(path, 0777) == 0;
    }
    JS_FreeCString(ctx, path);
    return JS_NewBool(ctx, ret);
}

static JSValue cc_chmod(JSContext *ctx, JSValueConst this_val,
                        int argc, JSValueConst *argv)
{
    const char *path = JS_ToCString(ctx, argv[0]);
    int mode = 0;
    int ret;

    (void)this_val;
    (void)argc;
    if (!path) return JS_EXCEPTION;
    if (JS_ToInt32(ctx, &mode, argv[1])) {
        JS_FreeCString(ctx, path);
        return JS_EXCEPTION;
    }
    ret = chmod(path, mode & 07777) == 0;
    JS_FreeCString(ctx, path);
    return JS_NewBool(ctx, ret);
}

static JSValue cc_cwd(JSContext *ctx, JSValueConst this_val,
                      int argc, JSValueConst *argv)
{
    char buf[4096];

    (void)this_val;
    (void)argc;
    (void)argv;
    if (!getcwd(buf, sizeof(buf))) return JS_ThrowPlainError(ctx, "getcwd failed");
    return JS_NewString(ctx, buf);
}

static JSValue cc_getenv(JSContext *ctx, JSValueConst this_val,
                         int argc, JSValueConst *argv)
{
    const char *name = JS_ToCString(ctx, argv[0]);
    const char *value;
    JSValue ret;

    (void)this_val;
    (void)argc;
    if (!name) return JS_EXCEPTION;
    value = getenv(name);
    JS_FreeCString(ctx, name);
    if (!value) return JS_UNDEFINED;
    ret = JS_NewString(ctx, value);
    return ret;
}

static JSValue cc_exit(JSContext *ctx, JSValueConst this_val,
                       int argc, JSValueConst *argv)
{
    int status = 0;

    (void)this_val;
    if (argc >= 1) JS_ToInt32(ctx, &status, argv[0]);
    fflush(stdout);
    fflush(stderr);
    exit(status);
    return JS_UNDEFINED;
}

static JSValue cc_write(JSContext *ctx, JSValueConst this_val,
                        int argc, JSValueConst *argv)
{
    int fd;
    size_t len;
    const char *text;
    FILE *fp;

    (void)this_val;
    if (JS_ToInt32(ctx, &fd, argv[0])) return JS_EXCEPTION;
    text = JS_ToCStringLen(ctx, &len, argv[1]);
    if (!text) return JS_EXCEPTION;
    fp = fd == 2 ? stderr : stdout;
    fwrite(text, 1, len, fp);
    fflush(fp);
    JS_FreeCString(ctx, text);
    return JS_NewInt64(ctx, (int64_t)len);
}

static void set_fn(JSContext *ctx, JSValueConst obj, const char *name,
                   JSCFunction *fn, int length)
{
    JS_SetPropertyStr(ctx, obj, name, JS_NewCFunction(ctx, fn, name, length));
}

static void install_native(JSContext *ctx, int argc, char **argv)
{
    JSValue global = JS_GetGlobalObject(ctx);
    JSValue native = JS_NewObject(ctx);
    JSValue args = JS_NewArray(ctx);
    int i;

    set_fn(ctx, native, "readFile", cc_read_file, 1);
    set_fn(ctx, native, "writeFile", cc_write_file, 2);
    set_fn(ctx, native, "exists", cc_exists, 1);
    set_fn(ctx, native, "stat", cc_stat, 1);
    set_fn(ctx, native, "readdir", cc_readdir, 1);
    set_fn(ctx, native, "mkdir", cc_mkdir, 2);
    set_fn(ctx, native, "chmod", cc_chmod, 2);
    set_fn(ctx, native, "cwd", cc_cwd, 0);
    set_fn(ctx, native, "getenv", cc_getenv, 1);
    set_fn(ctx, native, "exit", cc_exit, 1);
    set_fn(ctx, native, "write", cc_write, 2);
    JS_SetPropertyStr(ctx, global, "__cc_native", native);

    for (i = 1; i < argc; i++) {
        JS_SetPropertyUint32(ctx, args, (uint32_t)(i - 1), JS_NewString(ctx, argv[i]));
    }
    JS_SetPropertyStr(ctx, global, "__cc_argv", args);
    JS_FreeValue(ctx, global);
}

static JSModuleDef *embedded_loader(JSContext *ctx, const char *module_name,
                                    void *opaque, JSValueConst attributes)
{
    const EmbeddedModule *found = NULL;
    size_t i;
    JSValue value;
    JSModuleDef *module;

    (void)opaque;
    (void)attributes;

    for (i = 0; i < cc_module_count; i++) {
        if (!strcmp(cc_modules[i].name, module_name)) {
            found = &cc_modules[i];
            break;
        }
    }
    if (!found) {
        const char *base = base_name(module_name);
        for (i = 0; i < cc_module_count; i++) {
            if (!strcmp(base_name(cc_modules[i].name), base)) {
                found = &cc_modules[i];
                break;
            }
        }
    }
    if (!found) {
        JS_ThrowReferenceError(ctx, "could not load embedded module '%s'",
                               module_name);
        return NULL;
    }

    value = JS_ReadObject(ctx, found->data, found->size, JS_READ_OBJ_BYTECODE);
    if (JS_IsException(value)) return NULL;
    if (JS_VALUE_GET_TAG(value) != JS_TAG_MODULE) {
        JS_FreeValue(ctx, value);
        JS_ThrowTypeError(ctx, "embedded module '%s' is not a module", module_name);
        return NULL;
    }
    /* the module is referenced by the runtime, so drop our reference */
    module = JS_VALUE_GET_PTR(value);
    JS_FreeValue(ctx, value);
    return module;
}

int main(int argc, char **argv)
{
    JSRuntime *rt;
    JSContext *ctx;
    int status;

    rt = JS_NewRuntime();
    if (!rt) {
        fprintf(stderr, "cc: cannot allocate JS runtime\n");
        return 2;
    }
    js_std_init_handlers(rt);
    ctx = JS_NewContext(rt);
    if (!ctx) {
        fprintf(stderr, "cc: cannot allocate JS context\n");
        return 2;
    }

    install_native(ctx, argc, argv);
    cc_init_modules();
    JS_SetModuleLoaderFunc2(rt, NULL, embedded_loader, NULL, NULL);
    js_std_add_helpers(ctx, 0, NULL);

    js_std_eval_binary(ctx, cc_bootstrap, cc_bootstrap_size, 0);
    js_std_eval_binary(ctx, cc, cc_size, 0);

    status = js_std_loop(ctx);
    if (status) js_std_dump_error(ctx);

    js_std_free_handlers(rt);
    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);
    return status;
}
